// VAT Summary Tests

test('vatSummary returns empty array when no invoices', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary filters out draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(draft.ok, true);

  const result = vatSummary([draft.value]);
  assert.deepEqual(result, []);
});

test('vatSummary includes issued invoices', () => {
  const inv = createTestInvoice('C-001', '2025-01-15');
  assert.equal(inv.ok, true);

  const result = vatSummary([inv.value]);
  assert.equal(result.length, 1);
  assert(result[0].rate > 0);
});

test('vatSummary includes partially_paid invoices', () => {
  const inv = createTestInvoice('C-001', '2025-01-15');
  assert.equal(inv.ok, true);

  const partial = recordPayment(inv.value, { amount: 50000, date: '2025-01-20' });
  assert.equal(partial.ok, true);

  const result = vatSummary([partial.value]);
  assert.equal(result.length, 1);
});

test('vatSummary includes paid invoices', () => {
  const inv = createTestInvoice('C-001', '2025-01-15');
  assert.equal(inv.ok, true);

  const { total } = invoiceTotals(inv.value);
  const paid = recordPayment(inv.value, { amount: total, date: '2025-01-20' });
  assert.equal(paid.ok, true);

  const result = vatSummary([paid.value]);
  assert.equal(result.length, 1);
});

test('vatSummary has correct structure', () => {
  const inv = createTestInvoice('C-001', '2025-01-15');
  assert.equal(inv.ok, true);

  const result = vatSummary([inv.value]);
  assert.equal(result.length, 1);

  const entry = result[0];
  assert(typeof entry.rate === 'number');
  assert(typeof entry.base === 'number');
  assert(typeof entry.vat === 'number');
  assert.equal(Object.keys(entry).length, 3);
});

test('vatSummary calculates correct base and vat', () => {
  const inv = createTestInvoice('C-001', '2025-01-15');
  assert.equal(inv.ok, true);

  const { subtotal, discount } = invoiceTotals(inv.value);
  const base = subtotal - discount;

  const result = vatSummary([inv.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].base, base);
  assert(result[0].vat > 0);
});

test('vatSummary groups by VAT rate', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });
  assert.equal(draft.ok, true);

  const inv = issueInvoice(draft.value, []);
  assert.equal(inv.ok, true);

  const result = vatSummary([inv.value]);
  assert.equal(result.length, 1);
  assert(result[0].rate > 0);
});

test('vatSummary with multiple different VAT rates', () => {
  const draft1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(draft1.ok, true);

  const inv1 = issueInvoice(draft1.value, []);
  assert.equal(inv1.ok, true);

  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-16',
    lines: [{ sku: 'MGMT-DAY', qty: 1 }],
  });
  assert.equal(draft2.ok, true);

  const inv2 = issueInvoice(draft2.value, []);
  assert.equal(inv2.ok, true);

  const result = vatSummary([inv1.value, inv2.value]);
  assert(result.length >= 1);
});

test('vatSummary accumulates bases and vats for same rate', () => {
  const draft1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(draft1.ok, true);

  const inv1 = issueInvoice(draft1.value, []);
  assert.equal(inv1.ok, true);

  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(draft2.ok, true);

  const inv2 = issueInvoice(draft2.value, []);
  assert.equal(inv2.ok, true);

  const result = vatSummary([inv1.value, inv2.value]);
  const invoiceTotal1 = invoiceTotals(inv1.value);
  const invoiceTotal2 = invoiceTotals(inv2.value);

  // Should have accumulated both into one entry
  assert(result.length >= 1);
  const entry = result.find(e => e.rate === 21);
  assert(entry.base > invoiceTotal1.subtotal - invoiceTotal1.discount);
});

test('vatSummary sorts by rate descending', () => {
  const draft1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(draft1.ok, true);

  const inv1 = issueInvoice(draft1.value, []);
  assert.equal(inv1.ok, true);

  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'MGMT-DAY', qty: 1 }],
  });
  assert.equal(draft2.ok, true);

  const inv2 = issueInvoice(draft2.value, []);
  assert.equal(inv2.ok, true);

  const result = vatSummary([inv2.value, inv1.value]);

  // Verify sorted descending
  for (let i = 1; i < result.length; i++) {
    assert(result[i - 1].rate >= result[i].rate);
  }
});

test('vatSummary with discounted line', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });
  assert.equal(draft.ok, true);

  const inv = issueInvoice(draft.value, []);
  assert.equal(inv.ok, true);

  const result = vatSummary([inv.value]);
  assert.equal(result.length, 1);
  assert(result[0].vat > 0);
  assert(result[0].base > 0);
});

test('vatSummary with multiple invoices of mixed status', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(draft.ok, true);

  const inv1 = issueInvoice(draft.value, []);
  assert.equal(inv1.ok, true);

  const partial = recordPayment(inv1.value, { amount: 50000, date: '2025-01-20' });
  assert.equal(partial.ok, true);

  const inv2 = createTestInvoice('C-002', '2025-01-20');
  assert.equal(inv2.ok, true);

  const { total } = invoiceTotals(inv2.value);
  const paid = recordPayment(inv2.value, { amount: total, date: '2025-01-25' });
  assert.equal(paid.ok, true);

  const result = vatSummary([partial.value, paid.value]);
  assert(result.length >= 1);
  assert(result[0].base > 0);
});

test('vatSummary with single line invoice', () => {
  const inv = createTestInvoice('C-001', '2025-01-15');
  assert.equal(inv.ok, true);

  const result = vatSummary([inv.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
});

test('vatSummary preserves precision in accumulation', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DES-HOUR', qty: 4 },
    ],
  });
  assert.equal(draft.ok, true);

  const inv = issueInvoice(draft.value, []);
  assert.equal(inv.ok, true);

  const result = vatSummary([inv.value]);
  assert.equal(result.length, 1);
  assert(Number.isInteger(result[0].base));
  assert(Number.isInteger(result[0].vat));
});

